import unittest

from catalog import resource_schema
from consumer import validate


class Tests(unittest.TestCase):
    def test_valid(self):
        self.assertTrue(validate({'id': 'r1', 'provider': 'local', 'metadata': {}}))

    def test_required(self):
        self.assertFalse(validate({'id': 'r1'}))

    def test_schema_contract(self):
        self.assertEqual(resource_schema(), {
            'id': str, 'provider': str, 'metadata': dict,
        })

    def test_each_field_is_required(self):
        valid = {'id': 'r1', 'provider': 'local', 'metadata': {}}
        for field in valid:
            with self.subTest(field=field):
                row = valid.copy()
                del row[field]
                self.assertFalse(validate(row))
        self.assertFalse(validate({}))

    def test_field_types(self):
        invalid_values = {
            'id': (None, 1, True, [], {}),
            'provider': (None, 1, True, [], {}),
            'metadata': (None, 1, True, [], '{}'),
        }
        for field, values in invalid_values.items():
            for value in values:
                with self.subTest(field=field, value=value):
                    row = {'id': 'r1', 'provider': 'local', 'metadata': {}}
                    row[field] = value
                    self.assertFalse(validate(row))

    def test_additional_fields_and_metadata_are_allowed(self):
        self.assertTrue(validate({
            'id': 'r1', 'provider': 'local',
            'metadata': {'labels': ['example'], 'count': 2},
            'description': 'An optional field',
        }))

    def test_schema_mutation_does_not_affect_other_consumers(self):
        schema = resource_schema()
        schema.clear()
        self.assertFalse(validate({'id': 'r1'}))
        self.assertEqual(resource_schema(), {
            'id': str, 'provider': str, 'metadata': dict,
        })

