import unittest

from dependency_fixture import dependencies


class DependenciesTests(unittest.TestCase):
    def test_preserves_names_order_and_duplicates(self):
        record = {"dependencies": ["parser", "storage", "parser"]}

        self.assertEqual(dependencies(record), ["parser", "storage", "parser"])

    def test_returns_a_new_list(self):
        record = {"dependencies": ["parser"]}

        result = dependencies(record)
        self.assertEqual(result, ["parser"])
        result.append("storage")

        self.assertEqual(record["dependencies"], ["parser"])
        self.assertIsNot(result, record["dependencies"])

    def test_missing_dependencies_returns_fresh_empty_lists(self):
        first = dependencies({})
        second = dependencies({})

        self.assertEqual(first, [])
        self.assertEqual(second, [])
        self.assertIsNot(first, second)

    def test_explicit_empty_dependencies_returns_a_new_list(self):
        record = {"dependencies": []}

        result = dependencies(record)

        self.assertEqual(result, [])
        self.assertIsNot(result, record["dependencies"])


if __name__ == "__main__":
    unittest.main()

